


import { useParams } from 'react-router-dom';
import ArticleDetail from '../../../components/ArticleItem/detailsArticle';


function ArticleDetailsPage({searchParams}) {
    
    const { id } = useParams(); // extrait l'id depuis l'URL
    //   const article = data.find((a) => a.id === Number(id)); // cherche l'article par ID
    // const searchParams = useSearchParams()
    const {data}  = searchParams;
    
  if (!data) {
    return <p> Article introuvable</p>;
  }

  const handleSubmit = (e) => {
    e.preventDefault();
    if (pseudo.trim() ==='' && texte.trim() ==='') return;

    const now = new Date();
    const date = now.toLocaleDateString("fr-FR");

    const inputCommentaire = {
      id: Date.now(), 
      key:id,
      pseudo:pseudo.trim(),
      texte:texte.trim(),
      date:date
    };
    
    setCommentaires([...commentaires, inputCommentaire]);
    setPseudo('');
    setTexte('');
  }
  return (
    <ArticleDetail handleSubmit={handleSubmit} id={id} article={data} />
  );
}

export default ArticleDetailsPage;
